from typing import Iterable, List, Literal, Tuple

Kind = Literal["debit", "credit"]

def running_balance(rows: Iterable[Tuple[int, Kind]]) -> List[int]:
    balance = 0
    out: List[int] = []
    for amount_cents, kind in rows:
        if kind == "credit":
            balance += amount_cents
        elif kind == "debit":
            balance -= amount_cents
        else:
            raise ValueError(f"unknown kind: {kind}")
        out.append(balance)
    return out
